import { afterEach, expect, it } from "D:/projexts/moe-next/node_modules/vitest/dist/index.js";
import { journeyWorld, closeStores, PROJECT_ID, GOAL_ID } from "D:/projexts/moe-next/apps/daemon/src/gates-journey-fixtures.ts";
import { installGateOptIns, resolveUnattendedPreview, startPreviewUnattended, autoPreviewDecision } from "D:/projexts/moe-next/apps/daemon/src/gates-unattended-fixtures.ts";
import { readCurrentActiveGraph } from "D:/projexts/moe-next/apps/daemon/src/planning/active-graph-projection.ts";
import { readPolicyRisk } from "D:/projexts/moe-next/apps/daemon/src/bootstrap/policy-risk-reader.ts";
import { readRunPolicyEvaluation } from "D:/projexts/moe-next/apps/daemon/src/bootstrap/run-policy-selection.ts";
import { readCriterionGoal } from "D:/projexts/moe-next/apps/daemon/src/criterion-evidence/criterion-goal.ts";
import { OPERATOR } from "D:/projexts/moe-next/apps/daemon/src/planning/plan-reject-test-fixtures.ts";
afterEach(closeStores);
it("measures the ordinary production journey without an injected preview risk record", async () => {
  const world = journeyWorld("SUBMITTED");
  installGateOptIns(world, [{ action: "preview.decide", tier: "R1" }, { action: "release.decide", tier: "R1" }]);
  const goal = readCriterionGoal(world.store, PROJECT_ID, GOAL_ID);
  if (!goal.ok || !goal.graph.planningRunRef) throw new Error("production journey has no goal-bound run");
  const runId = goal.graph.planningRunRef;
  const runRisk = readRunPolicyEvaluation(world.store, { projectId: PROJECT_ID, runId });
  const active = readCurrentActiveGraph(world.store, PROJECT_ID);
  const planRisk = readPolicyRisk(world.store, PROJECT_ID, OPERATOR, "plan.approve");
  const previewRisk = readPolicyRisk(world.store, PROJECT_ID, OPERATOR, "preview.decide");
  const riskAggregates = world.store.enumerateAggregateIdsByPrefix("policy-risk:sha256:");
  const riskEvents = riskAggregates.reduce((n, id) => n + world.store.readEvents(id).length, 0);
  const resolved = resolveUnattendedPreview(world);
  const receiptId = await startPreviewUnattended(world);
  const decision = autoPreviewDecision(world, receiptId);
  console.log("ORDINARY_PREVIEW_RISK_PROBE", JSON.stringify({ runId, runRisk, active, planRisk, previewRisk, riskAggregates: riskAggregates.length, riskEvents, resolved, decision }));
  expect(runRisk).toMatchObject({ ok: true, evaluation: { runId, riskTier: "R1" } });
  expect(active).toMatchObject({ ok: false, code: "ACTIVE_GRAPH_ABSENT" });
  expect(planRisk).toMatchObject({ ok: false, code: "POLICY_RISK_RECORD_MISSING", tier: null, truthClass: "UNKNOWN" });
  expect(previewRisk).toMatchObject({ ok: false, code: "POLICY_RISK_RECORD_MISSING", tier: null, truthClass: "UNKNOWN" });
  expect(riskAggregates).toHaveLength(0);
  expect(riskEvents).toBe(0);
  expect(resolved).toMatchObject({ ok: false, code: "PREVIEW_AUTO_NOT_ALLOWED", layer: "CORE_REDUCER", reasonCodes: expect.arrayContaining(["RISK_TIER_UNCLASSIFIABLE"]) });
  expect(decision).toBeNull();
});
